export const PlanProductIncentiveTargetType = {
  category: "category",
  vendor: "vendor",
  product: "product",
  new_customer: "new_customer",
  task: "task",
} as const;

/**
 * Set when targetType = new_customer. "flat" pays flatBonusCents per new customer; "pct_first_order" pays bonusPct % of the customer's first order; "pct_first_year_cumulative" pays bonusPct % of the combined total of every qualifying order the customer places in their first 12 months.
 * @nullable
 */
export type PlanProductIncentiveNewCustomerPayoutMode =
  | (typeof PlanProductIncentiveNewCustomerPayoutMode)[keyof typeof PlanProductIncentiveNewCustomerPayoutMode]
  | null;

export const PlanProductIncentiveNewCustomerPayoutMode = {
  flat: "flat",
  pct_first_order: "pct_first_order",
  pct_first_year_cumulative: "pct_first_year_cumulative",
} as const;

export interface PlanProductIncentive {
  id: number;
  planId: number;
  /** What the incentive matches on. category/vendor/product match sales; new_customer rewards landing a new customer; task rewards completing a named one-off task. */
  targetType: PlanProductIncentiveTargetType;
  /**
   * Product-line name matched when targetType = category.
   * @nullable
   */
  productCategory?: string | null;
  /**
   * Vendor matched when targetType = vendor.
   * @nullable
   */
  vendorId?: number | null;
  /**
   * Resolved vendor name (when targetType = vendor).
   * @nullable
   */
  vendorName?: string | null;
  /**
   * Product matched when targetType = product.
   * @nullable
   */
  productId?: number | null;
  /**
   * Resolved product name (when targetType = product).
   * @nullable
   */
  productName?: string | null;
  /**
   * For task targets, the task name. For other targets, an optional display label.
   * @nullable
   */
  label?: string | null;
  /**
   * For category/vendor/product, a % bonus on net margin of matching sales. For new_customer with pct_first_order mode, a % of the customer's first order total. Mutually exclusive with flatBonusCents.
   * @nullable
   */
  bonusPct?: number | null;
  /**
   * Flat dollar bonus (in cents). For new_customer (flat mode) = $ per new customer. For task = $ per approved completion. Mutually exclusive with bonusPct.
   * @nullable
   */
  flatBonusCents?: number | null;
  /**
   * Set when targetType = new_customer. "flat" pays flatBonusCents per new customer; "pct_first_order" pays bonusPct % of the customer's first order; "pct_first_year_cumulative" pays bonusPct % of the combined total of every qualifying order the customer places in their first 12 months.
   * @nullable
   */
  newCustomerPayoutMode?: PlanProductIncentiveNewCustomerPayoutMode;
}

