export interface WorkOrderItem {
  id: number;
  workOrderId: number;
  /** @nullable */
  productId?: number | null;
  /** @nullable */
  productName?: string | null;
  /** @nullable */
  sku?: string | null;
  /** @nullable */
  unit?: string | null;
  quantity: number;
  unitPrice: number;
  totalPrice: number;
  /**
   * Per-unit cost of the product at read time, used to compute the line margin. Null when the product is unknown.
   * @nullable
   */
  cost?: number | null;
  /**
   * Gross margin % of this line ((unitPrice - cost) / unitPrice * 100). Null when unit price is non-positive.
   * @nullable
   */
  marginPct?: number | null;
  /**
   * Resolved minimum margin floor for the product (override > category > none). Null when no floor is configured.
   * @nullable
   */
  marginFloorPct?: number | null;
  /**
   * Where marginFloorPct came from — a per-product override, the product category threshold, or null when no floor applies.
   * @nullable
   */
  marginFloorSource?: WorkOrderItemMarginFloorSource;
  /** True when a floor is configured and the line margin sits below it. */
  belowMarginFloor?: boolean;
  /** True when this below-floor line was saved via a recorded manager/admin override. */
  marginFloorOverride?: boolean;
  /**
   * Name of the manager/admin who approved the margin-floor override, when recorded.
   * @nullable
   */
  marginFloorOverrideByName?: string | null;
  /**
   * When the margin-floor override was approved, when recorded.
   * @nullable
   */
  marginFloorOverrideAt?: string | null;
  /**
   * Optional free-text rationale the approving manager gave for the below-floor override, for finance review.
   * @nullable
   */
  marginFloorOverrideReason?: string | null;
  /**
   * Links this line to an AgroLiquid blanket allocation request, when the line was sourced from one.
   * @nullable
   */
  blanketAllocationId?: number | null;
  /**
   * Status of the linked blanket allocation (pending | approved | denied | cancelled). Drives whether the line price is shown or hidden as pending. Null for ordinary lines.
   * @nullable
   */
  blanketAllocationStatus?: string | null;
  /**
   * How the line is physically fulfilled, independent of blanket pricing. "inventory" draws from a tank/bin; "direct_ship" ships from the manufacturer. Resolved to the product default when the stored value is null.
   * @nullable
   */
  fulfillmentSource?: WorkOrderItemFulfillmentSource;
  /**
   * For inventory lines, the tank/bin this line draws from. Null = unassigned (picking resolves the site default tank).
   * @nullable
   */
  fulfillmentStockLocationId?: number | null;
  /** The product's default direct-ship flag, used to resolve the effective fulfillment source when fulfillmentSource is null. */
  isDirectShip?: boolean;
  /**
   * Identifies the AgroLiquid blend ("combo mix") this line was added with. Lines sharing a key form one mix; the visible "Combo Mix N" number is derived from the order of distinct keys on the work order. Null for ordinary lines.
   * @nullable
   */
  comboMixKey?: string | null;
  /**
   * Target application rate (gal/acre) the combo blend was built at in the calculator, shared across every line of the blend. Drives the per-acre rate chart on the printed/emailed document. Null on older lines created before the rate was captured, and on ordinary non-blend lines.
   * @nullable
   */
  comboRatePerAcre?: number | null;
  createdAt: string;
}

